$utf8=New-Object Text.UTF8Encoding($false,$true);function Json($v,[int]$d=50){$t=($v|ConvertTo-Json -Depth $d).Replace("`r`n","`n").Replace("`r","`n");if(-not$t.EndsWith("`n")){$t+="`n"};return $t};function Atomic([string]$p,$v,[int]$d=50){$parent=Split-Path -Parent $p;if(-not(Test-Path $parent)){New-Item -ItemType Directory -Path $parent|Out-Null};$tmp=$p+'.tmp-'+[Guid]::NewGuid().ToString('N');[IO.File]::WriteAllText($tmp,(Json $v $d),$utf8);if(Test-Path $p){$bak=$p+'.bak-'+[Guid]::NewGuid().ToString('N');[IO.File]::Replace($tmp,$p,$bak);if(Test-Path $bak){[IO.File]::Delete($bak)}}else{[IO.File]::Move($tmp,$p)}};function Create([string]$p,$v,[int]$d=50){if(Test-Path $p){throw "Create-new target exists: $p"};Atomic $p $v $d};function ReadJ([string]$p){Get-Content -Raw $p|ConvertFrom-Json};function Hash([string]$p){(Get-FileHash $p -Algorithm SHA256).Hash.ToLowerInvariant()}
